const out = [];

$input.all().forEach((item, i) => {
  const b = item.json.body && typeof item.json.body === 'object' ? item.json.body : {};
  let ev = null;

  if (b.triggerEvent) {
    const p = b.payload || {};
    const a = (p.attendees || [])[0] || {};
    const map = { BOOKING_CREATED: 'booked', BOOKING_RESCHEDULED: 'rescheduled', BOOKING_CANCELLED: 'cancelled' };
    if (map[b.triggerEvent]) ev = { event: map[b.triggerEvent], email: a.email, name: a.name, consult_at: p.startTime, booking_ref: p.uid, provider: 'cal.com' };
  } else if (b.event && b.payload) {
    const p = b.payload;
    if (b.event === 'invitee.created') {
      ev = { event: p.old_invitee ? 'rescheduled' : 'booked', email: p.email, name: p.name, consult_at: p.scheduled_event && p.scheduled_event.start_time, booking_ref: p.uri, provider: 'calendly' };
    } else if (b.event === 'invitee.canceled' && !p.rescheduled) {
      ev = { event: 'cancelled', email: p.email, name: p.name, consult_at: '', booking_ref: p.uri, provider: 'calendly' };
    }
  } else if (b.email) {
    const status = String(b.status || 'booked').toLowerCase();
    ev = { event: ['cancelled', 'canceled'].includes(status) ? 'cancelled' : status === 'rescheduled' ? 'rescheduled' : 'booked', email: b.email, name: b.name, consult_at: b.start_time || b.consult_at, booking_ref: b.id || '', provider: 'custom' };
  }

  if (ev && ev.email) {
    out.push({
      json: { ...ev, email: String(ev.email).trim().toLowerCase(), name: ev.name || '', consult_at: ev.consult_at || '', booking_ref: ev.booking_ref || '' },
      pairedItem: { item: i },
    });
  }
});

return out;

const lc = (v) => String(v ?? '').trim().toLowerCase();
const firstName = (name) => String(name || '').trim().split(/\s+/)[0] || 'there';

const cfg = $('Config').first().json;
const bk = $('Normalize Booking').first().json;
const lead = $input.all().map((i) => i.json).find((r) => lc(r.email) === bk.email) || null;
const now = new Date().toISOString();

const start = bk.consult_at ? DateTime.fromISO(bk.consult_at).setZone(cfg.timezone) : null;
const when = start && start.isValid ? start.toFormat("cccc d LLLL 'at' h:mm a ZZZZ") : 'your booked time';
const name = (lead && lead.name) || bk.name;
const first = firstName(name);
const cancelled = bk.event === 'cancelled';

let emailSubject;
let emailBody;
let coachAlert;

if (cancelled) {
  emailSubject = 'No problem - here is a new link whenever you are ready';
  emailBody = [
    `Hi ${first},`,
    '',
    'I saw you cancelled our call, and that is completely fine - life gets busy.',
    '',
    `Whenever the timing works, you can grab a new slot here: ${cfg.bookingUrl}`,
    '',
    'If something about coaching is holding you back, just reply and tell me. Happy to answer questions by email first.',
    '',
    cfg.coachName,
  ].join('\n');
  coachAlert = `❌ Consult cancelled: ${name || bk.email}${lead ? ` (${lead.tier || 'no tier'}, ${lead.fit_score || '?'}/100)` : ''}\nA rebooking email was sent automatically.`;
} else {
  emailSubject = bk.event === 'rescheduled' ? `Updated: our call on ${when}` : `You're booked: our call on ${when}`;
  emailBody = [
    `Hi ${first},`,
    '',
    `${bk.event === 'rescheduled' ? 'Thanks for moving our call - the new time is' : 'Looking forward to our call on'} ${when}.`,
    '',
    'To get the most out of our time together, have a think about:',
    '1. What would make the next three months a win for you?',
    '2. What a normal week looks like - work, sleep, family, training.',
    '3. What has stopped you before, so we can plan around it.',
    '',
    'If you have any injuries or health conditions, bring them up on the call so I can plan safely around them.',
    '',
    'Talk soon,',
    cfg.coachName,
  ].join('\n');

  const brief = lead
    ? [
        `Tier: ${String(lead.tier || '?').toUpperCase()} (${lead.fit_score || '?'}/100) | Goal: ${lead.goal || '?'}`,
        `Start: ${lead.timeline || '?'} | Budget: ${lead.budget || '?'} | Experience: ${lead.experience || '?'}`,
        '',
        lead.ai_summary || '',
        lead.health_flags ? `\n⚠️ Health: ${lead.health_flags}` : '',
        lead.talking_points ? '\nAsk on the call:\n' + String(lead.talking_points).split(' | ').map((p) => `• ${p}`).join('\n') : '',
      ].join('\n')
    : 'No application on file - they booked directly. Cover goal, schedule, budget and health history on the call.';

  coachAlert = `${bk.event === 'rescheduled' ? '🔁 Consult rescheduled' : '📅 Consult booked'}: ${name || bk.email} - ${when}\n\n${brief}\n\n${bk.email}${lead && lead.phone ? ' | ' + lead.phone : ''}`.replace(/\n{3,}/g, '\n\n');
}

return [
  {
    json: {
      lead_id: (lead && lead.lead_id) || 'L-' + Date.now().toString(36).toUpperCase(),
      created_at: (lead && lead.created_at) || now,
      name: name || '',
      email: bk.email,
      source: (lead && lead.source) || 'booking link',
      status: cancelled ? 'cancelled' : 'booked',
      consult_at: cancelled ? '' : bk.consult_at,
      last_contact_at: now,
      email_subject: emailSubject,
      email_body: emailBody,
      coach_alert: coachAlert,
    },
    pairedItem: { item: 0 },
  },
];
